css:
@keyframes rise{
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.card.s-yAb83hwcyOaR{
    border: 1px solid var(--line-soft);
    border-radius: var(--radius);
    background: var(--bg-raised);
    margin: 6px 0;
    overflow: hidden;
  }

.head.s-yAb83hwcyOaR{
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    padding: 8px 11px;
    text-align: left;
    min-height: 38px;
    cursor: pointer;
  }

.chev.s-yAb83hwcyOaR{
    display: inline-block;
    color: var(--ink-faint);
    transition: transform var(--tap) var(--ease);
    font-size: 15px;
    line-height: 1;
  }

.summary.s-yAb83hwcyOaR{
    font-family: var(--mono);
    font-size: 11.5px;
    color: var(--ink-dim);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    flex: 1;
    min-width: 0;
  }

.badge.s-yAb83hwcyOaR{
    font-size: 10.5px;
    color: var(--ink-faint);
    border: 1px solid var(--line);
    border-radius: 999px;
    padding: 1px 6px;
    white-space: nowrap;
  }

.event-head.s-WovOnquG99wn{
    display: flex; align-items: center; gap: 6px; max-width: 100%; min-height: 24px;
    padding: 2px 8px 2px 4px; border-radius: 6px; cursor: pointer; text-align: left;
    font-family: var(--mono); font-size: 11.5px; color: var(--ink-faint);
  }

.stamp.s-WovOnquG99wn{
    font-size: 10.5px;
    color: var(--ink-faint);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    pointer-events: none;
    user-select: none;
  }

.head.s-256rrhKtGA7i{
    display: flex; align-items: center; gap: 6px;
    width: 100%;
    padding: 5px 8px;
    border: 1px solid var(--line-soft);
    border-radius: var(--radius);
    background: var(--bg-raised);
    font-family: var(--sans); font-size: 12.2px; color: var(--ink-dim);
    text-align: left;
  }

.column.s-FyadV6CSt3qI{
    max-width: calc(var(--column) + 2 * var(--column-gutter));
    margin: 0 auto;
    padding: 0 var(--column-gutter) 24px;
  }
